from pathlib import Path
import re, hashlib
p=Path('dist/index.html')
s=p.read_text()
m=re.search(r'<script id="bt-bet365-import-v2">\n(.*?)\n</script>',s,re.S)
assert m, 'Bet365 v2 script missing'
js=m.group(1)
js=js.replace('const STORE_KEY="bet-tracker-live-v1";','const STORE_KEY="bet-tracker-live-v1",BET365_TABLE_IMPORT_VERSION="v3-pdf-to-table";',1)
js=js.replace('const importPanel=()=>activeImportPanel||importPanel();','const importPanel=()=>activeImportPanel||document.querySelector("#bt365-dedicated-import")||document.querySelector("#bt-import-bets");',1)
needle='  const inRange=(d,from,to)=>d>=from&&d<=to;\n'
cache='''  const CACHE_DB="bettracker-import-cache-v1",CACHE_STORE="bet365-tables";\n  const fileKey=f=>`${f.name}|${f.size}|${f.lastModified}`;\n  function openCache(){return new Promise((resolve,reject)=>{const r=indexedDB.open(CACHE_DB,1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(CACHE_STORE))db.createObjectStore(CACHE_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}\n  async function getCachedTable(key){try{const db=await openCache();return await new Promise((resolve,reject)=>{const tx=db.transaction(CACHE_STORE,"readonly"),r=tx.objectStore(CACHE_STORE).get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}catch{return null}}\n  async function putCachedTable(key,value){try{const db=await openCache();await new Promise((resolve,reject)=>{const tx=db.transaction(CACHE_STORE,"readwrite");tx.objectStore(CACHE_STORE).put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}catch(e){console.warn("Bet365 conversion cache",e)}}\n'''
assert needle in js
js=js.replace(needle,needle+cache,1)
js=js.replace('status.textContent=`Reading Bet365 page ${pageNo} of ${doc.numPages}…`;','status.textContent=`Converting Bet365 page ${pageNo} of ${doc.numPages} into table rows…`;',1)
ma=re.search(r'  async function analyseBet365\(\)\{.*?\n  \}\n  function likelyKey',js,re.S); assert ma
analyse='''  async function analyseBet365(){\n    const panel=importPanel(),status=panel?.querySelector("#bt-import-status"),btn=panel?.querySelector("#bt-read-import"),file=panel?.querySelector("#bt-import-statement")?.files?.[0],from=panel?.querySelector("#bt365-from")?.value,to=panel?.querySelector("#bt365-to")?.value;\n    if(!status||!btn)return;if(!file){status.textContent="Choose the Bet365 statement PDF first.";status.className="bt-import-status err";return}\n    if(!from||!to||from>to){status.textContent="Choose a valid From and To date first.";status.className="bt-import-status err";return}\n    btn.disabled=true;status.className="bt-import-status";\n    try{\n      const pdf=await loadPdf(),bytes=new Uint8Array(await file.arrayBuffer()),doc=await pdf.getDocument({data:bytes}).promise,w=await getWorker(status),key=fileKey(file);\n      let cached=await getCachedTable(key),summary=cached?.summary||null,allRows=Array.isArray(cached?.rows)?cached.rows:[],pagesRead=Number(cached?.pagesRead)||0,detectedRows=Number(cached?.detectedRows)||0;\n      if(!summary)summary=await statementSummary(doc,w,status);\n      let olderStreak=0,seenAnyDate=allRows.some(r=>r.date),cachedOldest=allRows.map(r=>r.date).filter(Boolean).sort()[0]||"";\n      if(cachedOldest&&cachedOldest<from){status.textContent=`Using cached Bet365 table conversion (${allRows.length} rows).`;await new Promise(r=>setTimeout(r,50))}\n      else{\n        if(pagesRead&&allRows.length)status.textContent=`Continuing cached table conversion from page ${pagesRead+1}…`;\n        for(let n=pagesRead+1;n<=doc.numPages;n++){const pg=await ocrGridPage(doc,n,w,status);pagesRead=n;allRows.push(...pg.rows);detectedRows+=pg.detectedRows;if(pg.oldest||pg.newest){seenAnyDate=true;if(pg.newest&&pg.newest<from)olderStreak++;else olderStreak=0;if(olderStreak>=2){await putCachedTable(key,{rows:allRows,pagesRead,detectedRows,summary,updatedAt:Date.now()});break}}else olderStreak=0;if(n%3===0||n===doc.numPages)await putCachedTable(key,{rows:allRows,pagesRead,detectedRows,summary,updatedAt:Date.now()})}\n      }\n      if(!seenAnyDate)throw new Error("The Bet365 table was detected, but dates could not be read from its cells.");\n      await putCachedTable(key,{rows:allRows,pagesRead,detectedRows,summary,updatedAt:Date.now()});\n      const groups=groupRows(allRows),built=buildData(groups,from,to,summary.closing),stakeGroups=groups.filter(g=>g.type==="Stake"&&g.date&&inRange(g.date,from,to)).length,gameStakeGroups=groups.filter(g=>g.type==="Games Stake"&&g.date&&inRange(g.date,from,to)).length,tableRows=allRows.filter(r=>r.date&&inRange(r.date,from,to));\n      current={...built,from,to,pagesRead,totalPages:doc.numPages,detectedRows,summary,stakeGroups,gameStakeGroups,structuredRows:tableRows,allStructuredRows:allRows};\n      if(!built.bets.length&&!built.transactions.length)throw new Error("No Bet365 bets or cash movements were found in those dates.");\n      status.textContent=`Converted ${tableRows.length} Bet365 table rows and found ${built.bets.length} bets plus ${built.transactions.length} deposits/withdrawals.`;status.className="bt-import-status ok";renderPreview()\n    }catch(e){console.error(e);status.textContent=e.message||"Could not convert that Bet365 statement to a table.";status.className="bt-import-status err"}finally{btn.disabled=false}\n  }\n  function likelyKey'''
js=js[:ma.start()]+analyse+js[ma.end():]
old='<strong>Grid-verified Bet365 import:</strong> Bet Tracker detects every ruled table row first, then OCR reads the cells inside those rows. This prevents missed OCR dates from making whole bets disappear. Sport, event/market description, selection, odds, result, stake/return and cash movements are read from the statement. ${current.pagesRead} of ${current.totalPages} pages were scanned; ${current.detectedRows||0} table rows were detected before OCR.</p><div class="bt-import-tools">'
new='<strong>PDF → table conversion:</strong> Bet Tracker first converts the ruled Bet365 PDF into structured rows with Date/Time, Reference, Type, Description, Odds, Result, Deduction and Addition columns. The bet importer then works from that table, just like an Excel import. ${current.pagesRead} of ${current.totalPages} pages were converted; ${current.detectedRows||0} physical table rows were detected.</p><div class="bt-import-tools"><button class="button secondary" id="bt365-show-table">View converted table</button>'
assert old in js; js=js.replace(old,new,1)
needle='</div><div class="bt-import-final"><div><label><input type="checkbox" id="bt365-cash" checked>'
raw='''</div><div id="bt365-raw-table" style="display:none;margin-top:12px"><div class="bt-import-table"><table><thead><tr><th>Date/Time</th><th>Reference</th><th>Type</th><th>Description</th><th>Odds</th><th>Result</th><th>Deduction</th><th>Addition</th></tr></thead><tbody>${(current.structuredRows||[]).map(r=>`<tr><td>${esc((r.date||"")+(r.time?" "+r.time:""))}</td><td>${esc(r.ref)}</td><td>${esc(r.type)}</td><td>${esc(r.description)}</td><td>${esc(r.oddsCell)}</td><td>${esc(r.result)}</td><td>${r.deduction?money(r.deduction):""}</td><td>${r.addition?money(r.addition):""}</td></tr>`).join("")}</tbody></table></div></div><div class="bt-import-final"><div><label><input type="checkbox" id="bt365-cash" checked>'''
assert needle in js; js=js.replace(needle,raw,1)
needle='checks.forEach(x=>x.onchange=count);count();box.querySelector("#bt365-all").onclick='
toggle='checks.forEach(x=>x.onchange=count);count();const showTable=box.querySelector("#bt365-show-table"),rawTable=box.querySelector("#bt365-raw-table");if(showTable&&rawTable)showTable.onclick=()=>{const open=rawTable.style.display!=="none";rawTable.style.display=open?"none":"block";showTable.textContent=open?"View converted table":"Hide converted table"};box.querySelector("#bt365-all").onclick='
assert needle in js; js=js.replace(needle,toggle,1)
js=js.replace('Upload your Bet365 Statement of All Transactions, choose the dates you want, preview the OCR-read records and then import them.','Upload your Bet365 Statement of All Transactions. Bet Tracker converts the PDF table into structured rows first, then imports from that table.')
js=js.replace("Bet365's PDF is image-based. Bet Tracker now detects the table grid and every row first, then uses OCR only to read each detected cell. This is slower on long histories but far less likely to miss bets.","Bet Tracker converts Bet365's ruled PDF table into structured columns first. The importer then processes those structured rows like an Excel table; OCR is only used to read text inside already-detected cells.")
js=js.replace('>Read Bet365 statement</button>','>Convert PDF to table</button>',1)
js=js.replace('Choose the Bet365 statement and dates, then read it. Bet Tracker scans every statement page down to your start date so bets are not skipped.','Choose the Bet365 statement and dates, then convert it. Once converted, changing/reviewing the same statement reuses the cached structured table instead of starting again.')
js=js.replace('read.textContent="Read Bet365 statement"','read.textContent="Convert PDF to table"')
js=js.replace('preview the OCR-read records before importing.','convert its PDF table into structured rows and preview them before importing.')
s=s[:m.start()]+'<script id="bt-bet365-import-v3">\n'+js+'\n</script>'+s[m.end():]
p.write_text(s)
b=p.read_bytes()
assert len(b)==422012,len(b)
assert hashlib.sha256(b).hexdigest()=='9f32e34c172fd48afc79a30e4051cd152cf3477b14d9cad8005f1b7e789a41a8'
for x in ['bt-bet365-import-v3','BET365_TABLE_IMPORT_VERSION="v3-pdf-to-table"','Convert PDF to table','PDF → table conversion','View converted table','bettracker-import-cache-v1']:
    assert x in s,x
assert 'bt-bet365-import-v2' not in s
print('Applied Bet365 PDF-to-table importer v3:',len(b),'bytes')
